S['CH0611B'] = [
    {'k': 'hook', 'ch': 'Mở đầu', 'moc': True, 'label': 'BSR – Lọc hóa dầu Bình Sơn', 'cap': ('NGÀNH CHU', 'KỲ'), 'cols': (WHITE, GOLD), 'chart': {'sym': 'BSRW', 'tf': 'W', 'weeks': 52, 'circles': [[7, 13.35, 'Đáy tuần 15/12: 13,35', 0.6], [18, 39.16, 'Đỉnh tuần 9/3: 39,16', 1.6], [51, 28.75, '28/10: 28,75', 2.6]]}, 'anh': 'oil refinery at night', 'say': 'Có một nghịch lý khiến nhiều người mới thua đau: mua cổ phiếu ngành chu kỳ vì P trên E rất thấp, rồi thấy lợi nhuận quay đầu và giá giảm mạnh. Ngành chu kỳ là ngành mà lợi nhuận lên xuống theo chu kỳ của giá hàng hóa hoặc nhu cầu kinh tế, như dầu khí, thép, phân bón, vận tải biển, thủy sản. Trong video này mình giải thích đặc điểm của ngành chu kỳ, vì sao P trên E thấp nhất thường lúc nguy hiểm nhất và P trên E cao nhất đôi khi lúc cơ hội nhất, cách đọc các giai đoạn của chu kỳ, và những chỉ báo nên theo dõi. Doanh nghiệp lọc hóa dầu trên biểu đồ là ví dụ minh họa, số liệu quý ba năm hai nghìn không trăm hai mươi sáu. Đây là kiến thức nền, không phải khuyến nghị.'},
    {'k': 'cards', 'ch': 'Chương 1 – Ngành chu kỳ là gì', 'moc': True, 'label': 'Đặc điểm: lợi nhuận phụ thuộc giá hàng hóa/nhu cầu', 'cap': ('CHU KỲ', 'LÀ GÌ?'), 'cols': (WHITE, GOLD), 'cards': [('Dầu khí, thép', 'giá hàng hóa', 'lợi nhuận dao động'), ('Vận tải biển', 'cước tàu', 'theo nhu cầu'), ('Phòng thủ', 'ổn định hơn', 'thực phẩm, dược')], 'anh': 'commodity cycle', 'say': 'Ngành chu kỳ là ngành mà doanh thu và lợi nhuận dao động mạnh theo một chu kỳ bên ngoài tầm kiểm soát của doanh nghiệp, như giá dầu, giá thép, giá phân bón, cước tàu hay tăng trưởng kinh tế. Doanh nghiệp tốt đến mấy cũng khó tránh khỏi dao động đó. Ngược lại, ngành phòng thủ như thực phẩm, dược, điện nước có nhu cầu ổn định hơn. Đặc điểm của ngành chu kỳ gồm biên lợi nhuận biến động lớn, đòn bẩy hoạt động cao tức chi phí cố định lớn nên chỉ cần doanh thu tăng chút đã làm lợi nhuận tăng vọt và ngược lại, và thị trường định giá chúng theo kỳ vọng về chu kỳ chứ không chỉ theo lợi nhuận hiện tại.'},
    {'k': 'bars', 'ch': 'Chương 2 – Ví dụ: lợi nhuận một doanh nghiệp lọc dầu qua 5 quý', 'moc': True, 'label': 'LNST theo quý của BSR (tỷ đồng)', 'cap': ('LỢI NHUẬN', 'NHẢY VỌT QUA 5 QUÝ'), 'cols': (WHITE, GOLD), 'bars': [('Q3/25', 908, BLUE, '908'), ('Q4/25', 3062, BLUE, '3.062'), ('Q1/26', 8265, GREEN, '8.265'), ('Q2/26', 7666, GREEN, '7.666'), ('Q3/26', 8968, GREEN, '8.968')], 'anh': 'oil price chart', 'say': 'Hãy xem một ví dụ cực đoan. Doanh nghiệp lọc hóa dầu trong video có lợi nhuận quý ba năm hai nghìn không trăm hai mươi lăm khoảng chín trăm tỷ đồng, quý bốn hơn ba nghìn tỷ, rồi nhảy lên hơn tám nghìn tỷ ở quý một năm hai nghìn không trăm hai mươi sáu, bảy nghìn sáu trăm tỷ ở quý hai và gần chín nghìn tỷ ở quý ba. Chỉ trong năm quý, lợi nhuận gấp gần mười lần. Biên lợi nhuận gộp quý ba đạt mười sáu phẩy hai phần trăm so với hai phẩy chín phần trăm cùng kỳ. Những biến động này không phải do doanh nghiệp bỗng trở nên giỏi gấp mười lần, mà chủ yếu do chênh lệch giữa giá sản phẩm và giá dầu thô.'},
    {'k': 'cards', 'ch': 'Chương 3 – Nghịch lý P/E trong ngành chu kỳ', 'moc': True, 'label': 'P/E theo giai đoạn chu kỳ', 'cap': ('NGHỊCH LÝ', 'P/E'), 'cols': (WHITE, GOLD), 'cards': [('P/E', '6,94', 'lợi nhuận ở đỉnh?'), ('ROE 4 quý', '40,5%', 'cao bất thường'), ('Giá tuần', '13,35 → 39,16', '15/12/25 → 9/3/26')], 'anh': 'turning point cycle peak', 'say': 'Đây là nghịch lý quan trọng nhất. Theo dữ liệu hai tháng mười một, doanh nghiệp ví dụ có P trên E khoảng sáu phẩy chín bốn, rất thấp, trong lúc ROE bốn quý lên bốn mươi phẩy năm phần trăm. Người mới nhìn thấy tưởng rất rẻ. Nhưng thị trường hiểu rằng lợi nhuận hiện tại đang ở mức rất cao so với bình thường, nên chỉ trả một mức giá thấp so với lợi nhuận đó. Khi chu kỳ đi xuống và lợi nhuận về mức trung bình, nếu giá không đổi thì P trên E sẽ tăng gấp nhiều lần. Ngược lại ở đáy chu kỳ, lợi nhuận rất thấp nên P trên E cực cao, nhưng nếu chu kỳ sắp phục hồi, đó lại có thể là giai đoạn giá trị nhất. Vì vậy với ngành chu kỳ, quy tắc rẻ khi P trên E thấp có thể đúng ngược.'},
    {'k': 'checklist', 'ch': 'Chương 4 – Bốn giai đoạn của chu kỳ', 'moc': True, 'label': 'Hình dung chu kỳ', 'cap': ('4 GIAI ĐOẠN', 'CỦA CHU KỲ'), 'cols': (WHITE, GOLD), 'items': [('Đáy: lợi nhuận thấp, tâm lý bi quan', BLUE), ('Phục hồi: giá và lợi nhuận bắt đầu tăng', GREEN), ('Đỉnh: lợi nhuận kỷ lục, mở rộng công suất', GOLD), ('Suy thoái: công suất dư, giá giảm', RED)], 'anh': 'wave cycle graph', 'say': 'Chu kỳ thường đi qua bốn giai đoạn. Đáy: nhu cầu yếu, giá thấp, lợi nhuận thấp hoặc lỗ, tâm lý bi quan, nhiều doanh nghiệp cắt giảm đầu tư. Phục hồi: nhu cầu cải thiện, giá nhích lên, lợi nhuận bắt đầu tăng. Đỉnh: giá cao, lợi nhuận kỷ lục, tâm lý lạc quan, doanh nghiệp tăng đầu tư mở rộng công suất. Suy thoái: công suất mới đưa vào cộng với nhu cầu chững lại làm giá giảm, lợi nhuận tụt nhanh. Điều thú vị là giá cổ phiếu thường đi trước lợi nhuận: chạm đáy trước khi lợi nhuận chạm đáy, và chạm đỉnh trước khi lợi nhuận chạm đỉnh. Trong biểu đồ ví dụ, giá tuần đã đi từ mười ba nghìn ba trăm lên gần ba mươi chín nghìn đồng trong chưa đầy ba tháng rồi lùi về khoảng hai mươi tám nghìn bảy trăm.'},
    {'k': 'checklist', 'ch': 'Chương 5 – Những biến số cần theo dõi', 'moc': True, 'label': 'Mỗi ngành mỗi biến số', 'cap': ('BIẾN SỐ', 'CẦN THEO DÕI'), 'cols': (WHITE, GOLD), 'items': [('Lọc dầu: chênh lệch giá sản phẩm – dầu thô', GOLD), ('Thép: giá thép, quặng, nhu cầu xây dựng', GOLD), ('Phân bón: giá khí, giá urê', GOLD), ('Vận tải biển: cước và số tàu mới', GOLD)], 'anh': 'data monitoring dashboard', 'say': 'Với ngành chu kỳ, thay vì chỉ nhìn P trên E, hãy theo dõi biến số quyết định chu kỳ. Với lọc dầu là chênh lệch giá sản phẩm và dầu thô. Với thép là giá thép, giá quặng, nhu cầu xây dựng. Với phân bón là giá khí, giá urê. Với vận tải biển là cước tàu và số tàu mới. Ngoài ra theo dõi công suất mới của toàn ngành, tồn kho, và chính sách của nhà nước. Biến số tốt là biến số thay đổi trước khi lợi nhuận báo cáo thay đổi, giúp bạn thấy chu kỳ sớm hơn. Đồng thời đọc báo cáo ban lãnh đạo để hiểu họ nhìn chu kỳ thế nào.'},
    {'k': 'cards', 'ch': 'Chương 6 – Định giá ngành chu kỳ đúng cách', 'moc': True, 'label': 'Dùng lợi nhuận trung bình, giá trị sổ sách và so với lịch sử', 'cap': ('ĐỊNH GIÁ', 'NGÀNH CHU KỲ'), 'cols': (WHITE, GOLD), 'cards': [('Cách 1', 'lợi nhuận TB nhiều năm', 'P/E chu kỳ'), ('Cách 2', 'P/B so lịch sử', 'ổn định hơn lợi nhuận'), ('Cách 3', 'vị trí trong chu kỳ', 'giá phản ánh gì?')], 'anh': 'valuation analysis spreadsheet', 'say': 'Có ba cách làm cẩn thận hơn. Một, dùng lợi nhuận trung bình nhiều năm, ví dụ năm đến mười năm, thay vì bốn quý gần nhất, để tính P trên E chu kỳ. Hai, dùng P trên B và so với khoảng dao động lịch sử của chính doanh nghiệp, vì giá trị sổ sách ít biến động hơn lợi nhuận. Ba, hỏi mình đang ở giai đoạn nào của chu kỳ và thị trường đã phản ánh gì rồi. Trong ví dụ, P trên B khoảng một phẩy sáu sáu theo dữ liệu hai tháng mười một. Con số này không nói rẻ hay đắt, nó nói rằng thị trường đang trả giá hơn giá trị sổ sách, cần đặt cạnh khoảng dao động lịch sử của chính doanh nghiệp và kỳ vọng về chu kỳ.'},
    {'k': 'checklist', 'ch': 'Chương 7 – Rủi ro đòn bẩy hoạt động', 'moc': True, 'label': 'Hai chiều của chi phí cố định', 'cap': ('ĐÒN BẨY', 'HOẠT ĐỘNG'), 'cols': (WHITE, GOLD), 'items': [('Doanh thu tăng chút → lợi nhuận tăng vọt', GREEN), ('Doanh thu giảm chút → lợi nhuận giảm mạnh', RED), ('Thêm lãi vay: cộng hưởng rủi ro', RED), ('Bảng cân đối vững: qua được đáy', GREEN)], 'anh': 'factory machines fixed cost', 'say': 'Ngành chu kỳ thường có chi phí cố định lớn như nhà máy, tàu, thiết bị. Khi doanh thu tăng chút ít, lợi nhuận tăng rất nhiều vì chi phí cố định đã được chia sẻ. Khi doanh thu giảm, lợi nhuận giảm nhanh hơn nhiều và có thể chuyển sang lỗ. Hiểu điều này giúp bạn không ngạc nhiên khi một doanh nghiệp lãi kỷ lục vài quý rồi lỗ vài quý. Nếu doanh nghiệp còn vay nợ nhiều, tác động càng lớn: lãi vay là chi phí cố định thứ hai. Doanh nghiệp ngành chu kỳ có bảng cân đối vững, nợ thấp, tiền mặt dày là những doanh nghiệp qua được đáy chu kỳ để hưởng phần tốt của đợt phục hồi sau.'},
    {'k': 'checklist', 'ch': 'Chương 8 – Sai lầm thường gặp khi đầu tư ngành chu kỳ', 'moc': True, 'label': 'Năm sai lầm', 'cap': ('5 SAI LẦM', 'NGÀNH CHU KỲ'), 'cols': (WHITE, GOLD), 'items': [('Mua vì P/E thấp ở đỉnh chu kỳ', RED), ('Ngoại suy lợi nhuận đỉnh', RED), ('Bỏ qua công suất mới của ngành', RED), ('Nhầm chu kỳ giảm là cơ hội', RED), ('Quên giới hạn tỷ trọng', RED)], 'anh': 'warning cycle trap', 'say': 'Những sai lầm mình gặp nhiều nhất. Mua vì P trên E thấp mà không hỏi lợi nhuận đang ở đâu trong chu kỳ. Ngoại suy lợi nhuận hiện tại ra nhiều năm. Bỏ qua công suất mới của toàn ngành. Nhầm giá cổ phiếu giảm là cơ hội khi thực ra chu kỳ mới bắt đầu đi xuống. Và ngược lại, bỏ lỡ cơ hội vì chỉ nhìn lợi nhuận đang rất xấu. Không ai bắt đúng đỉnh và đáy, nhưng nếu bạn biết chu kỳ ở đâu, bạn ít nhất không tăng tỷ trọng đúng lúc mọi người hưng phấn nhất. Tỷ trọng ngành chu kỳ trong danh mục nên có giới hạn rõ ràng, như nguyên tắc phân bổ đã nói trong video trước.'},
    {'k': 'checklist', 'ch': 'Chương 8b – Ngành chu kỳ trong thị trường Việt Nam', 'moc': True, 'label': 'Một số nhóm ngành chu kỳ phổ biến', 'cap': ('NHÓM NGÀNH', 'CHU KỲ PHỔ BIẾN'), 'cols': (WHITE, GOLD), 'items': [('Dầu khí, thép, phân bón', GOLD), ('Cảng biển, vận tải biển', GOLD), ('Thủy sản, gỗ xuất khẩu', GOLD), ('Bất động sản, chứng khoán', GOLD)], 'anh': 'Vietnam industries port steel fishery', 'say': 'Ở Việt Nam, nhiều nhóm ngành mang tính chu kỳ rõ rệt. Dầu khí và lọc hóa dầu theo giá dầu và chênh lệch giá sản phẩm. Thép và vật liệu xây dựng theo nhu cầu xây dựng và giá nguyên liệu. Phân bón theo giá khí và giá nông sản. Cảng biển và vận tải biển theo thương mại quốc tế và cước tàu. Thủy sản và gỗ theo nhu cầu xuất khẩu. Bất động sản theo lãi suất và pháp lý. Chứng khoán cũng là ngành chu kỳ vì doanh thu gắn với thanh khoản thị trường. Điều này không có nghĩa là cổ phiếu các ngành này luôn xấu; nó nghĩa là cách đọc P trên E và lợi nhuận quý phải khác với cổ phiếu tiêu dùng hay công nghệ có lợi nhuận ổn định hơn.'},
    {'k': 'checklist', 'ch': 'Chương 9 – Tóm tắt và bước tiếp theo', 'moc': True, 'label': 'Ghi nhớ', 'cap': ('TÓM TẮT', '5 Ý CHÍNH'), 'cols': (WHITE, GOLD), 'items': [('Lợi nhuận dao động theo yếu tố bên ngoài', GOLD), ('P/E thấp nhất thường ở đỉnh lợi nhuận', RED), ('Theo dõi biến số của ngành', GOLD), ('Định giá bằng trung bình nhiều năm', GOLD), ('Ưu tiên bảng cân đối vững', GREEN)], 'anh': 'summary notes', 'say': 'Tóm lại năm ý. Một, ngành chu kỳ có lợi nhuận dao động theo yếu tố bên ngoài. Hai, P trên E thấp nhất thường trùng đỉnh lợi nhuận. Ba, xác định giai đoạn chu kỳ bằng biến số của ngành chứ không chỉ bằng báo cáo quý. Bốn, định giá bằng lợi nhuận trung bình nhiều năm và P trên B so lịch sử. Năm, ưu tiên doanh nghiệp có bảng cân đối vững và giới hạn tỷ trọng. Khi bạn hiểu ngành chu kỳ, bạn cũng hiểu vì sao tin tức lợi nhuận kỷ lục đôi khi đi cùng giá giảm. Hãy áp dụng cách nhìn này cho thép, phân bón, vận tải biển, thủy sản, và bất kỳ ngành nào có giá hàng hóa quyết định biên lợi nhuận.'},
    {'k': 'end', 'label': '', 'cap': ('NGÀNH CHU KỲ', 'P/E THẤP CHƯA PHẢI RẺ'), 'cols': (WHITE, GOLD), 'say': 'Số liệu của doanh nghiệp trong video lấy từ báo cáo tài chính quý ba năm hai nghìn không trăm hai mươi sáu và dữ liệu tổng hợp ngày hai tháng mười một, dùng làm ví dụ minh họa. Nội dung chia sẻ kiến thức, không phải khuyến nghị mua bán chứng khoán. Bảng định giá có tại chungkhoanhuynguyen chấm com.'},
]

S['CH0611C'] = [
    {'k': 'hook', 'ch': 'Mở đầu', 'moc': True, 'label': 'Chỉ số VN30 – 52 tuần gần nhất', 'cap': ('CÚ SẬP', '2008'), 'cols': (WHITE, GOLD), 'chart': {'sym': 'VN30W', 'tf': 'W', 'weeks': 52, 'circles': [[10, 2121.13, 'Đỉnh tuần 5/1: 2121', 0.6], [20, 1737.11, 'Đáy tuần 23/3: 1737', 1.6], [51, 1890.22, '28/10: 1890', 2.6]]}, 'anh': 'stock crash 2008 trading floor', 'say': 'Cuối năm hai nghìn không trăm lẻ bảy VN-Index còn quanh chín trăm ba mươi điểm. Đến cuối năm hai nghìn không trăm lẻ tám chỉ còn quanh ba trăm mười lăm điểm. Và ngày hai mươi bốn tháng hai năm hai nghìn không trăm lẻ chín, chỉ số đóng cửa quanh hai trăm ba mươi lăm điểm, thấp hơn đỉnh tháng ba năm hai nghìn không trăm lẻ bảy khoảng tám mươi phần trăm. Biểu đồ trên là chỉ số VN ba mươi mười hai tháng gần đây để so với hiện tại, còn câu chuyện hôm nay là cú sập năm hai nghìn không trăm lẻ tám. Video thuộc seri Bài học lịch sử, tiếp theo video về bong bóng năm hai nghìn không trăm lẻ bảy. Các mốc điểm số lấy từ số liệu công bố của sở giao dịch, làm tròn, và nội dung chỉ để rút bài học.'},
    {'k': 'cards', 'ch': 'Chương 1 – Sau đỉnh: mọi thứ xấu đi cùng lúc', 'moc': True, 'label': 'Các cú sốc năm 2008', 'cap': ('BA CÚ SỐC', 'CÙNG LÚC'), 'cols': (WHITE, GOLD), 'cards': [('Lạm phát', '≈ gần 20%', 'cả năm 2008'), ('Lãi suất', 'tăng mạnh', 'tín dụng siết'), ('Khủng hoảng toàn cầu', 'vốn ngoại rút', 'thị trường mới nổi')], 'anh': '2008 financial crisis newspaper', 'say': 'Năm hai nghìn không trăm lẻ tám, thị trường Việt Nam chịu ba cú sốc cùng lúc. Một, lạm phát trong nước lên rất cao, gần hai mươi phần trăm theo số liệu cả năm, buộc chính sách tiền tệ thắt chặt, lãi suất tăng mạnh, tín dụng bị siết. Hai, tỷ giá và cán cân thương mại căng thẳng. Ba, từ giữa năm đến mùa thu, khủng hoảng tài chính toàn cầu nổ ra, dòng vốn nước ngoài rút khỏi các thị trường mới nổi. Với những người đã vay tiền mua cổ phiếu năm trước, lãi suất cao và giá giảm là tổ hợp tệ nhất. Mỗi cú sốc riêng lẻ có thể chịu được, nhưng ba cú sốc đồng thời làm niềm tin biến mất.'},
    {'k': 'bars', 'ch': 'Chương 2 – Con đường đi xuống', 'moc': True, 'label': 'Mốc điểm VN-Index (làm tròn)', 'cap': ('1.170 XUỐNG 235', '−80%'), 'cols': (WHITE, GOLD), 'bars': [('Đỉnh 3/2007', 1170, RED, '≈1.170'), ('Cuối 2007', 930, BLUE, '≈930'), ('Cuối 2008', 315, BLUE, '≈315'), ('Đáy 2/2009', 235, RED, '≈235')], 'anh': 'Vietnam stock exchange 2009', 'say': 'Hãy nhìn các mốc. Đỉnh ngày mười hai tháng ba năm hai nghìn không trăm lẻ bảy quanh một nghìn một trăm bảy mươi điểm. Cuối năm hai nghìn không trăm lẻ bảy quanh chín trăm ba mươi. Cuối năm hai nghìn không trăm lẻ tám quanh ba trăm mười lăm. Đáy ngày hai mươi bốn tháng hai năm hai nghìn không trăm lẻ chín quanh hai trăm ba mươi lăm điểm. Từ đỉnh đến đáy, chỉ số mất khoảng tám mươi phần trăm trong chưa đầy hai năm. Để hòa vốn từ đáy lên đỉnh cũ, chỉ số cần tăng gần năm lần, một chặng đường mất nhiều năm. Đây là minh họa sống động của toán học khoản lỗ.'},
    {'k': 'checklist', 'ch': 'Chương 3 – Đòn bẩy phá hủy như thế nào', 'moc': True, 'label': 'Cơ chế bán giải chấp', 'cap': ('BÁN GIẢI CHẤP', 'TỰ NUÔI GIẢM'), 'cols': (WHITE, GOLD), 'items': [('Giá giảm → yêu cầu bổ sung tài sản', RED), ('Không bổ sung → bị bán giải chấp', RED), ('Bán giải chấp đẩy giá giảm thêm', RED), ('Không dùng đòn bẩy → có quyền chờ', GREEN)], 'anh': 'margin call alert', 'say': 'Khi giá giảm, những tài khoản dùng tiền vay bị công ty chứng khoán yêu cầu bổ sung tài sản đảm bảo, nếu không bổ sung sẽ bị bán giải chấp. Lệnh bán giải chấp đẩy giá giảm thêm, kéo thêm tài khoản khác vào vùng bị bán, tạo vòng xoáy tự nuôi. Thêm vào đó, nhiều nhà đầu tư dùng chính cổ phiếu để thế chấp vay thêm, nên giá giảm làm hạn mức vay giảm, buộc bán thêm. Đây là lý do những ngày giảm sâu trong lịch sử thường có thanh khoản rất lớn bên bán và gần như không có người mua. Người không dùng đòn bẩy không bị buộc bán, họ có quyền lựa chọn chờ, và quyền lựa chọn đó có giá trị rất lớn.'},
    {'k': 'checklist', 'ch': 'Chương 4 – Tâm lý đám đông ở đáy', 'moc': True, 'label': 'Những câu nói thường nghe ở đáy', 'cap': ('TÂM LÝ', 'Ở ĐÁY'), 'cols': (WHITE, GOLD), 'items': [('Ai cũng nói chứng khoán đã chết', RED), ('Thanh khoản co lại, diễn đàn vắng', RED), ('Doanh nghiệp tốt dưới giá trị sổ sách', GOLD), ('Cần tiền mặt và kế hoạch chia nhỏ', GREEN)], 'anh': 'empty trading room despair', 'say': 'Ở đáy thị trường, tâm lý hoàn toàn ngược lại với đỉnh. Người ta nói chứng khoán đã chết, không bao giờ quay lại nữa, đóng tài khoản, chuyển sang vàng hay bất động sản. Khối lượng giao dịch co lại, các diễn đàn vắng lặng, tin tức chỉ toàn xấu. Chính trong bầu không khí đó, giá cổ phiếu của nhiều doanh nghiệp tốt xuống thấp hơn giá trị sổ sách. Nhưng điều nguy hiểm là chúng ta không bao giờ biết đáy ở đâu cho đến khi nó qua đi. Nhiều người nghĩ đã rẻ rồi và mua sớm, rồi bị lỗ tiếp. Bài học không phải là bắt đáy, mà là có sẵn tiền mặt, có kế hoạch mua chia nhỏ theo thời gian, và chỉ mua những doanh nghiệp bảng cân đối đủ vững để sống qua giai đoạn.'},
    {'k': 'cards', 'ch': 'Chương 5 – Điều gì giúp một số người vượt qua', 'moc': True, 'label': 'Ba đặc điểm chung', 'cap': ('3 ĐIỀU', 'GIÚP VƯỢT QUA'), 'cols': (WHITE, GOLD), 'cards': [('Không đòn bẩy', 'không bị ép bán', 'có quyền chờ'), ('Thu nhập khác', 'không cần rút vốn', 'bình tĩnh'), ('Kỷ luật', 'thực hiện kế hoạch', 'dù xung quanh hoảng sợ')], 'anh': 'resilience climbing mountain', 'say': 'Trong các câu chuyện của những người vượt qua cú sập năm hai nghìn không trăm lẻ tám, có ba đặc điểm chung. Một, họ không dùng hoặc dùng rất ít đòn bẩy, nên không bị buộc bán ở đáy. Hai, họ có nguồn thu nhập khác ngoài chứng khoán, nên không cần rút tiền vào lúc giá thấp. Ba, họ có kỷ luật thực hiện kế hoạch: nhiều người đã viết sẵn khi nào giảm tỷ trọng, khi nào bổ sung, và thực hiện kể cả khi mọi người xung quanh hoảng sợ. Đáng chú ý là không có đặc điểm nào về chuyện dự báo đúng. Sống sót và thực hiện kỷ luật là hai năng lực quan trọng hơn dự báo.'},
    {'k': 'checklist', 'ch': 'Chương 6 – Bài học về thanh khoản và niềm tin', 'moc': True, 'label': 'Hai điều ít được nhắc', 'cap': ('THANH KHOẢN', 'VÀ NIỀM TIN'), 'cols': (WHITE, GOLD), 'items': [('Cổ phiếu nhỏ thanh khoản thấp: khó thoát', RED), ('Ưu tiên cổ phiếu có thanh khoản tốt', GREEN), ('Xác minh thông tin từ nguồn chính thức', GREEN), ('Tin đồn trong nhóm: cẩn trọng', RED)], 'anh': 'information rumor whisper', 'say': 'Hai bài học ít được nhắc. Thứ nhất là thanh khoản: có lúc bạn muốn bán nhưng không ai mua ở mức giá hợp lý, đặc biệt với cổ phiếu nhỏ. Nếu cổ phiếu chiếm tỷ trọng lớn trong danh mục mà thanh khoản yếu, bạn gần như không thể thoát khi cần. Thứ hai là niềm tin vào thông tin: ở thị trường còn non, thông tin kém minh bạch hơn, tin đồn có sức mạnh lớn. Ngày nay quy định công bố thông tin đã chặt chẽ hơn nhiều, nhưng tin đồn vẫn còn. Vì vậy hãy xác minh thông tin từ báo cáo tài chính và công bố chính thức của doanh nghiệp, thay vì tin lời truyền miệng trong nhóm.'},
    {'k': 'checklist', 'ch': 'Chương 7 – So sánh với bây giờ', 'moc': True, 'label': 'Thị trường hôm nay khác gì', 'cap': ('SO VỚI', 'HÔM NAY'), 'cols': (WHITE, GOLD), 'items': [('Thị trường lớn hơn, minh bạch hơn', GREEN), ('Con người vẫn lặp lại hành vi', GOLD), ('Biến động bình thường ≠ sụp đổ', GOLD), ('Đòn bẩy, thanh khoản, kỷ luật: vẫn là cốt lõi', GREEN)], 'anh': 'Vietnam financial district modern', 'say': 'Hôm nay quy mô thị trường lớn hơn rất nhiều, có nhà đầu tư tổ chức, quỹ ngoại và hệ thống giao dịch hiện đại. Theo nến tuần, chỉ số VN ba mươi mười hai tháng gần đây có đỉnh tuần khoảng hai nghìn một trăm hai mươi mốt điểm vào đầu tháng một và đáy tuần khoảng một nghìn bảy trăm ba mươi bảy điểm vào cuối tháng ba, tức biên độ khoảng mười tám phần trăm, rồi hiện ở khoảng một nghìn tám trăm chín mươi. Đây là một chu kỳ điều chỉnh bình thường chứ không phải sụp đổ. Điều muốn nói là lịch sử không lặp lại y nguyên nhưng con người thì có xu hướng lặp lại, và những bài học về đòn bẩy, thanh khoản và kỷ luật vẫn còn nguyên giá trị.'},
    {'k': 'cards', 'ch': 'Chương 7b – Nhìn lại bằng con số hòa vốn', 'moc': True, 'label': 'Cần tăng bao nhiêu để về lại', 'cap': ('TOÁN HỌC', 'CỦA KHOẢN LỖ'), 'cols': (WHITE, GOLD), 'cards': [('Lỗ 50%', 'cần +100%', 'gấp đôi'), ('Lỗ 80%', 'cần +400%', 'gấp năm'), ('Bài học', 'giới hạn lỗ', 'ngay từ đầu')], 'anh': 'mountain climbing steep hill', 'say': 'Hãy dùng lại toán học của khoản lỗ để hiểu vì sao cú sập này khủng khiếp đến vậy. Giảm tám mươi phần trăm cần tăng bốn trăm phần trăm để hòa vốn, tức gấp năm lần. Một người mua gần đỉnh năm hai nghìn không trăm lẻ bảy mà không bán, nếu giữ cổ phiếu chỉ số, phải chờ rất nhiều năm. Một số cổ phiếu phục hồi sớm, số khác mất nhiều năm, và có doanh nghiệp không bao giờ về lại mức cũ. Điều này cho thấy tại sao các nhà đầu tư kỳ cựu luôn nhấn mạnh việc giới hạn khoản lỗ từ đầu thay vì kỳ vọng thị trường sẽ cứu mình. Bảo toàn vốn là bài học quan trọng nhất của mọi lần sập, ở mọi thời đại.'},
    {'k': 'checklist', 'ch': 'Chương 8 – Bốn bài học chính', 'moc': True, 'label': 'Tổng kết', 'cap': ('4 BÀI HỌC', 'TỪ 2008'), 'cols': (WHITE, GOLD), 'items': [('Nhiều cú sốc có thể xảy ra cùng lúc', GOLD), ('Đòn bẩy biến biến động thành bị ép bán', RED), ('Đáy không biết trước: chia nhỏ, giữ tiền mặt', GOLD), ('Còn vốn và kỷ luật mới hưởng được hồi phục', GREEN)], 'anh': 'lessons learned books', 'say': 'Bốn bài học từ năm hai nghìn không trăm lẻ tám. Một, ba cú sốc cùng lúc có thể xảy ra, nên đừng để mức rủi ro của bạn dựa vào kịch bản một cú sốc. Hai, đòn bẩy biến biến động thành bị ép bán. Ba, đáy không ai biết trước, nên chia nhỏ theo thời gian và giữ tiền mặt. Bốn, sau mỗi cú sập thị trường vẫn tồn tại và doanh nghiệp tốt vẫn tạo giá trị, nhưng chỉ người còn vốn và còn kỷ luật mới hưởng được phần đó. Mình hy vọng video này giúp bạn nhìn biến động hiện tại bình tĩnh hơn. Ở video sau của seri, mình sẽ kể về ba cú giảm lớn của những năm hai nghìn không trăm mười tám, hai nghìn không trăm hai mươi và hai nghìn không trăm hai mươi hai.'},
    {'k': 'end', 'label': '', 'cap': ('BÀI HỌC LỊCH SỬ', '2008'), 'cols': (WHITE, GOLD), 'say': 'Các mốc điểm số năm hai nghìn không trăm lẻ bảy đến hai nghìn không trăm lẻ chín lấy từ số liệu công bố của sở giao dịch chứng khoán, làm tròn. Số liệu chỉ số VN ba mươi mười hai tháng gần nhất lấy từ nến tuần đến ngày hai mươi tám tháng mười năm hai nghìn không trăm hai mươi sáu. Nội dung chia sẻ kiến thức, không phải dự báo hay khuyến nghị mua bán chứng khoán.'},
]
